using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;
    private Func<HttpListenerResponse, Task> respond = _ => Task.CompletedTask;

    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? ContentType { get; private set; }
    public string? Body { get; private set; }

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{baseAddress}");
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
        _ = Task.Run(Serve);
    }

    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint()
    {
        Reply(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", Method);
        Assert.Equal("/v1/authorizations", Path);
        Assert.StartsWith("application/json", ContentType);
        using var json = JsonDocument.Parse(Body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_approved()
    {
        Reply(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_declined()
    {
        Reply(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Reply(200, """{"id":"abc","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_declined_even_with_a_non_json_body()
    {
        Reply(402, "Payment Required", "text/plain");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_approved_looking_body_is_still_declined()
    {
        Reply(402, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_failures_not_declines(int status)
    {
        Reply(status, """{"error":"nope"}""");
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_exact_approval_is_never_approved(string body)
    {
        Reply(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("""{"status":{"code":1}}""")]
    public async Task An_unreadable_answer_is_a_failure(string body)
    {
        Reply(200, body);
        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    private HttpPaymentGateway Gateway() => new(client);

    private Task<AuthorizationOutcome> Authorize() =>
        Gateway().AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private void Reply(int status, string body, string contentType = "application/json") =>
        respond = async response =>
        {
            response.StatusCode = status;
            response.ContentType = contentType;
            var bytes = Encoding.UTF8.GetBytes(body);
            await response.OutputStream.WriteAsync(bytes);
        };

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch { return; }

            Method = context.Request.HttpMethod;
            Path = context.Request.Url!.AbsolutePath;
            ContentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                Body = await reader.ReadToEndAsync();
            await respond(context.Response);
            context.Response.Close();
        }
    }

    private static int FreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
